-- Function: public.fn_get_child_memories
-- Backup generated on 2026-10-25 20:33:10

CREATE OR REPLACE FUNCTION public.fn_get_child_memories(p_tenant_id uuid, p_child_id uuid, p_is_parent boolean, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_category character varying DEFAULT NULL::character varying, p_search_query character varying DEFAULT NULL::character varying, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)  RETURNS TABLE(id uuid, tenant_id uuid, event_date timestamp with time zone, event_type character varying, category character varying, title character varying, description text, source_id uuid, source_type character varying, child_id uuid, child_name character varying, classroom_id uuid, classroom_name character varying, teacher_id uuid, teacher_name character varying, experience_id uuid, experience_title character varying, media_url text, is_parent_visible boolean, status character varying, category_icon character varying)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT * FROM (         -- 1. Child Stories         SELECT              cs.id, cs.tenant_id, cs.created_at AS event_date,             'Observation'::VARCHAR AS event_type,             'Observations'::VARCHAR AS category,             'Story'::VARCHAR AS title,             cs.content AS description,             cs.id AS source_id,             'child_stories'::VARCHAR AS source_type,             cs.child_id,             (c.first_name || ' ' || c.last_name)::VARCHAR AS child_name,             NULL::UUID AS classroom_id,             NULL::VARCHAR AS classroom_name,             cs.teacher_id,             COALESCE(t.first_name || ' ' || t.last_name, 'Teacher')::VARCHAR AS teacher_name,             es.experience_id,             e.title::VARCHAR AS experience_title,             NULL::TEXT AS media_url,             TRUE AS is_parent_visible,             cs.status::VARCHAR,             'bi-journal-text'::VARCHAR AS category_icon         FROM child_stories cs         JOIN children c ON cs.child_id = c.id         LEFT JOIN experience_schedules es ON cs.experience_schedule_id = es.id         LEFT JOIN experiences e ON es.experience_id = e.id         LEFT JOIN teachers t ON cs.teacher_id = t.id         WHERE cs.tenant_id = p_tenant_id AND cs.child_id = p_child_id           AND (p_is_parent = FALSE OR cs.status = 'Approved')          UNION ALL                  -- 2. Child Journey Entries         SELECT              je.id, je.tenant_id, je.observation_date AS event_date,             (CASE WHEN je.is_milestone THEN 'Milestone' ELSE 'Observation' END)::VARCHAR AS event_type,             (CASE WHEN je.is_milestone THEN 'Milestones' ELSE 'Observations' END)::VARCHAR AS category,             COALESCE(je.title, 'Journey Entry')::VARCHAR AS title,             je.observation AS description,             je.id AS source_id,             'child_journey_entries'::VARCHAR AS source_type,             je.child_id,             (c.first_name || ' ' || c.last_name)::VARCHAR AS child_name,             je.classroom_id,             cr.name::VARCHAR AS classroom_name,             je.teacher_id,             COALESCE(t.first_name || ' ' || t.last_name, 'Teacher')::VARCHAR AS teacher_name,             je.experience_id,             e.title::VARCHAR AS experience_title,             ev.text_content AS media_url,             je.is_parent_visible,             je.parent_visibility_status::VARCHAR AS status,             (CASE WHEN je.is_milestone THEN 'bi-trophy' ELSE 'bi-compass' END)::VARCHAR AS category_icon         FROM child_journey_entries je         JOIN children c ON je.child_id = c.id         LEFT JOIN classrooms cr ON je.classroom_id = cr.id         LEFT JOIN experiences e ON je.experience_id = e.id         LEFT JOIN teachers t ON je.teacher_id = t.id         LEFT JOIN LATERAL (             SELECT cje_ev.text_content              FROM child_journey_evidence cje_ev             WHERE cje_ev.journey_entry_id = je.id              ORDER BY cje_ev.created_at DESC              LIMIT 1         ) ev ON TRUE         WHERE je.tenant_id = p_tenant_id AND je.child_id = p_child_id           AND (p_is_parent = FALSE OR (je.is_parent_visible = TRUE AND (je.parent_visibility_status = 'Approved' OR je.parent_visibility_status IS NULL)))          UNION ALL          -- 3. Experience Participations         SELECT              s.id, s.tenant_id,             (s.session_date + COALESCE(s.end_time, s.start_time, '00:00:00'::TIME))::TIMESTAMPTZ AS event_date,             'Session'::VARCHAR AS event_type,             'Learning Experiences'::VARCHAR AS category,             COALESCE(e.title, 'Experience Session')::VARCHAR AS title,             COALESCE(p.participation_notes, s.actual_notes, 'Child participated in this learning experience.') AS description,             p.id AS source_id,             'experience_participations'::VARCHAR AS source_type,             p.child_id,             (c.first_name || ' ' || c.last_name)::VARCHAR AS child_name,             s.classroom_id,             cr.name::VARCHAR AS classroom_name,             s.primary_teacher_id AS teacher_id,             COALESCE(t.first_name || ' ' || t.last_name, 'Teacher')::VARCHAR AS teacher_name,             s.experience_id,             e.title::VARCHAR AS experience_title,             NULL::TEXT AS media_url,             TRUE AS is_parent_visible,             p.participation_status::VARCHAR AS status,             'bi-palette'::VARCHAR AS category_icon         FROM experience_participations p         JOIN experience_sessions s ON p.experience_session_id = s.id         JOIN children c ON p.child_id = c.id         LEFT JOIN classrooms cr ON s.classroom_id = cr.id         LEFT JOIN experiences e ON s.experience_id = e.id         LEFT JOIN teachers t ON s.primary_teacher_id = t.id         WHERE s.tenant_id = p_tenant_id            AND p.child_id = p_child_id            AND p.participation_status = 'Participated'          UNION ALL          -- 4. Child Milestones         SELECT             m.id, m.tenant_id, m.milestone_date AS event_date,             'Milestone'::VARCHAR AS event_type,             'Milestones'::VARCHAR AS category,             m.title::VARCHAR,             COALESCE(m.description, m.evidence_summary, 'Developmental milestone achieved.') AS description,             m.id AS source_id,             'child_milestones'::VARCHAR AS source_type,             m.child_id,             (c.first_name || ' ' || c.last_name)::VARCHAR AS child_name,             m.classroom_id,             cr.name::VARCHAR AS classroom_name,             m.teacher_id,             COALESCE(t.first_name || ' ' || t.last_name, 'Teacher')::VARCHAR AS teacher_name,             NULL::UUID AS experience_id,             NULL::VARCHAR AS experience_title,             NULL::TEXT AS media_url,             m.parent_visible AS is_parent_visible,             m.status::VARCHAR,             'bi-star-fill'::VARCHAR AS category_icon         FROM child_milestones m         JOIN children c ON m.child_id = c.id         LEFT JOIN classrooms cr ON m.classroom_id = cr.id         LEFT JOIN teachers t ON m.teacher_id = t.id         WHERE m.tenant_id = p_tenant_id AND m.child_id = p_child_id           AND (p_is_parent = FALSE OR m.parent_visible = TRUE)          UNION ALL          -- 5. Celebrations & Events         SELECT             r.id, ev.tenant_id,             (ev.event_date + COALESCE(ev.start_time, '09:00:00'::TIME))::TIMESTAMPTZ AS event_date,             'Celebration'::VARCHAR AS event_type,             'Celebrations'::VARCHAR AS category,             ev.title::VARCHAR,             COALESCE(ev.description, r.notes, 'Celebration & Daycare Event') AS description,             ev.id AS source_id,             'events'::VARCHAR AS source_type,             r.child_id,             (c.first_name || ' ' || c.last_name)::VARCHAR AS child_name,             NULL::UUID AS classroom_id,             NULL::VARCHAR AS classroom_name,             NULL::UUID AS teacher_id,             'Daycare Staff'::VARCHAR AS teacher_name,             NULL::UUID AS experience_id,             NULL::VARCHAR AS experience_title,             NULL::TEXT AS media_url,             TRUE AS is_parent_visible,             r.status::VARCHAR,             'bi-balloon-heart'::VARCHAR AS category_icon         FROM event_rsvps r         JOIN events ev ON r.event_id = ev.id         JOIN children c ON r.child_id = c.id         WHERE ev.tenant_id = p_tenant_id            AND r.child_id = p_child_id           AND ev.status = 'Published'           AND r.status IN ('Accepted', 'Attended', 'Confirmed')          UNION ALL          -- 6. Child Daily Care & Wellbeing         SELECT             ce.id, ce.tenant_id, ce.event_time AS event_date,             'DailyCare'::VARCHAR AS event_type,             'Daily Care'::VARCHAR AS category,             ('Wellbeing Highlight: ' || ce.comfort_mood)::VARCHAR AS title,             COALESCE(ce.notes, 'Positive daily care & comfort milestone.') AS description,             ce.id AS source_id,             'child_care_events'::VARCHAR AS source_type,             ce.child_id,             (c.first_name || ' ' || c.last_name)::VARCHAR AS child_name,             ce.classroom_id,             cr.name::VARCHAR AS classroom_name,             ce.recorded_by_user_id AS teacher_id,             ce.recorded_by_name::VARCHAR AS teacher_name,             NULL::UUID AS experience_id,             NULL::VARCHAR AS experience_title,             NULL::TEXT AS media_url,             ce.parent_visible AS is_parent_visible,             'Recorded'::VARCHAR AS status,             'bi-sun'::VARCHAR AS category_icon         FROM child_care_events ce         JOIN children c ON ce.child_id = c.id         LEFT JOIN classrooms cr ON ce.classroom_id = cr.id         WHERE ce.tenant_id = p_tenant_id            AND ce.child_id = p_child_id           AND ce.event_type = 'Comfort'           AND ce.comfort_mood IN ('Happy', 'Settled')           AND (p_is_parent = FALSE OR ce.parent_visible = TRUE)     ) AS combined     WHERE (p_start_date IS NULL OR combined.event_date >= p_start_date)       AND (p_end_date IS NULL OR combined.event_date <= p_end_date)       AND (p_category IS NULL OR p_category = 'All' OR combined.category = p_category)       AND (p_search_query IS NULL OR p_search_query = '' OR combined.title ILIKE '%' || p_search_query || '%' OR combined.description ILIKE '%' || p_search_query || '%')       AND (p_is_parent = FALSE OR combined.is_parent_visible = TRUE)     ORDER BY combined.event_date DESC     LIMIT p_limit OFFSET p_offset; END; $function$ ;
